#include "vll/practice/ProgressionPractice.h"
#include <algorithm>
namespace vll::practice {bool ProgressionPractice::validate(const PracticePlan&p)const{return !p.id.empty()&&!p.progression.empty()&&p.choruses>0&&p.voiceCount>=2&&p.voiceCount<=4&&std::ranges::all_of(p.progression,[](const auto&e){return !e.symbol.empty()&&!e.pitchClasses.empty();});}PracticeEvaluation ProgressionPractice::evaluate(const PracticePlan&p,const std::vector<Sonority>&s)const{PracticeEvaluation r;if(!validate(p)){r.observations.push_back({"invalid_plan","Practice plan is invalid."});return r;}const auto expected=p.progression.size()*static_cast<std::size_t>(p.choruses);if(s.size()!=expected){r.observations.push_back({"event_count","Expected "+std::to_string(expected)+" events; received "+std::to_string(s.size())+"."});return r;}for(std::size_t i=0;i<s.size();++i){if(static_cast<int>(s[i].pitches.size())!=p.voiceCount){r.observations.push_back({"voice_count","Event "+std::to_string(i+1)+" has the wrong voice count."});return r;}const auto& allowed=p.progression[i%p.progression.size()].pitchClasses;for(auto note:s[i].pitches)if(std::ranges::find(allowed,note.pitchClass())==allowed.end()){r.observations.push_back({"non_chord_tone","Event "+std::to_string(i+1)+" contains a pitch outside its harmony."});return r;}}r.accepted=true;r.completedChoruses=p.choruses;r.observations.push_back({"practice_complete",std::to_string(p.choruses)+" choruses satisfied the plan."});return r;}}
